//! Port-number parsing.
//!
//! The C++ library feeds the text after the host/port `:` straight into
//! `std::stoi` and swallows the exceptions, then range-checks the result.
//! Reproducing that exactly matters: `std::stoi` skips leading whitespace,
//! honours a leading sign, stops at the first non-digit and only reports
//! failure when there are no digits at all or the value leaves `int`.

/// Sentinel written into `URL::port` when no usable port was found.
pub const NO_PORT: i32 = -1;

/// Smallest accepted port number.
pub const MIN_PORT: i32 = 0;

/// Largest accepted port number.
pub const MAX_PORT: i32 = 65535;

/// `std::isspace` under the default "C" locale.
fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Emulates `std::stoi(text)`.
///
/// Returns `None` where the C++ call would throw: `std::invalid_argument`
/// when no digits could be consumed, `std::out_of_range` when the value does
/// not fit in an `int`.
pub fn stoi(text: &[u8]) -> Option<i32> {
    let mut i = 0;
    while i < text.len() && is_space(text[i]) {
        i += 1;
    }

    let mut negative = false;
    if i < text.len() && (text[i] == b'+' || text[i] == b'-') {
        negative = text[i] == b'-';
        i += 1;
    }

    let digits_start = i;
    // Accumulate in i64 and stop growing once we are provably past the `int`
    // range, so absurdly long digit runs cannot overflow the accumulator.
    let mut value: i64 = 0;
    let mut overflowed = false;
    while i < text.len() && text[i].is_ascii_digit() {
        if !overflowed {
            value = value * 10 + i64::from(text[i] - b'0');
            if value > i64::from(u32::MAX) {
                overflowed = true;
            }
        }
        i += 1;
    }

    if i == digits_start {
        return None; // std::invalid_argument
    }
    if overflowed {
        return None; // std::out_of_range
    }

    let signed = if negative { -value } else { value };
    if signed > i64::from(i32::MAX) || signed < i64::from(i32::MIN) {
        return None; // std::out_of_range
    }
    Some(signed as i32)
}

/// Parses the text following the authority's `:` into a port number.
///
/// Yields [`NO_PORT`] when `std::stoi` would have thrown or when the number
/// falls outside `0..=65535`.
pub fn parse_port(text: &[u8]) -> i32 {
    match stoi(text) {
        Some(value) if (MIN_PORT..=MAX_PORT).contains(&value) => value,
        _ => NO_PORT,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn stoi_matches_libstdcxx() {
        assert_eq!(stoi(b"80"), Some(80));
        assert_eq!(stoi(b"+80"), Some(80));
        assert_eq!(stoi(b"-80"), Some(-80));
        assert_eq!(stoi(b" \t\n80"), Some(80));
        assert_eq!(stoi(b"80abc"), Some(80));
        assert_eq!(stoi(b"0x10"), Some(0));
        assert_eq!(stoi(b"007"), Some(7));
        assert_eq!(stoi(b"1e3"), Some(1));
        assert_eq!(stoi(b"-0"), Some(0));
        assert_eq!(stoi(b"2147483647"), Some(i32::MAX));
        assert_eq!(stoi(b"-2147483648"), Some(i32::MIN));

        assert_eq!(stoi(b""), None);
        assert_eq!(stoi(b"abc"), None);
        assert_eq!(stoi(b"+"), None);
        assert_eq!(stoi(b" "), None);
        assert_eq!(stoi(b"2147483648"), None);
        assert_eq!(stoi(b"18446744073709551617"), None);
        assert_eq!(stoi(b"99999999999999999999999999999999"), None);
    }

    #[test]
    fn port_range_is_inclusive_0_to_65535() {
        assert_eq!(parse_port(b"0"), 0);
        assert_eq!(parse_port(b"65535"), 65535);
        assert_eq!(parse_port(b"65536"), NO_PORT);
        assert_eq!(parse_port(b"-80"), NO_PORT);
        assert_eq!(parse_port(b"abc"), NO_PORT);
        assert_eq!(parse_port(b""), NO_PORT);
        assert_eq!(parse_port(b"80abc"), 80);
    }
}
=== PARSER ===
//! The splitting algorithm.
//!
//! Component boundaries are decided in a fixed order, which is what makes
//! `"/path?x=http://y"` come out as a plain path plus query rather than
//! sprouting a scheme:
//!
//! 1. the first `#` peels off the fragment,
//! 2. the first `?` in what is left peels off the query,
//! 3. the first `://` in what is left peels off the scheme and opens an
//!    authority; without it the whole remainder is the path,
//! 4. inside the authority the first `/` ends it and starts the path, the
//!    first `@` splits off the userinfo, and the first `:` splits off the port.
//!
//! Every delimiter is ASCII, so slicing the input at the offsets found here
//! never lands inside a multi-byte UTF-8 sequence.

use super::port::{parse_port, NO_PORT};
use super::Parts;

/// Byte offset of the first occurrence of `needle` in `haystack`.
fn find(haystack: &[u8], needle: u8) -> Option<usize> {
    haystack.iter().position(|&b| b == needle)
}

/// Byte offset of the first occurrence of the `://` separator.
fn find_scheme_separator(haystack: &[u8]) -> Option<usize> {
    haystack.windows(3).position(|w| w == b"://")
}

/// ASCII-only lowercasing, matching `std::tolower` under the "C" locale:
/// bytes outside `A-Z` — including every byte of a UTF-8 sequence — are kept.
fn ascii_lowercase(bytes: &[u8]) -> Vec<u8> {
    bytes.iter().map(|b| b.to_ascii_lowercase()).collect()
}

/// Splits `input` into its components.
pub fn parse(input: &[u8]) -> Parts {
    let mut parts = Parts {
        scheme: Vec::new(),
        userinfo: Vec::new(),
        host: Vec::new(),
        port: NO_PORT,
        path: Vec::new(),
        query: Vec::new(),
        fragment: Vec::new(),
    };

    let mut rest = input;

    // 1. Fragment: everything after the first '#'. A later '#' stays inside
    //    the fragment, so "#a#b" yields the fragment "a#b".
    if let Some(hash) = find(rest, b'#') {
        parts.fragment = rest[hash + 1..].to_vec();
        rest = &rest[..hash];
    }

    // 2. Query: everything after the first '?' of the pre-fragment text. A '?'
    //    that appeared after the '#' already belongs to the fragment.
    if let Some(question) = find(rest, b'?') {
        parts.query = rest[question + 1..].to_vec();
        rest = &rest[..question];
    }

    // 3. Scheme: the text before the first "://". A bare "scheme:" is not
    //    enough — "mailto:user@example.com" has no scheme and no authority.
    match find_scheme_separator(rest) {
        Some(sep) => {
            parts.scheme = ascii_lowercase(&rest[..sep]);
            let after = &rest[sep + 3..];

            // 4. Authority runs up to the first '/', which begins the path.
            let authority = match find(after, b'/') {
                Some(slash) => {
                    parts.path = after[slash..].to_vec();
                    &after[..slash]
                }
                None => after,
            };

            // Userinfo is delimited by the first '@'; a second '@' is left in
            // the host, so "a@b@c.com" has userinfo "a" and host "b@c.com".
            let host_port = match find(authority, b'@') {
                Some(at) => {
                    parts.userinfo = authority[..at].to_vec();
                    &authority[at + 1..]
                }
                None => authority,
            };

            // The first ':' separates host from port. There is no IPv6
            // bracket handling, so "[::1]:80" leaves the host as "[".
            match find(host_port, b':') {
                Some(colon) => {
                    parts.host = host_port[..colon].to_vec();
                    parts.port = parse_port(&host_port[colon + 1..]);
                }
                None => parts.host = host_port.to_vec(),
            }
        }
        // Without "://" there is no authority at all: the remainder, leading
        // slashes and colons included, is the path.
        None => parts.path = rest.to_vec(),
    }

    parts
}
=== SER ===
//! Re-serialisation of parsed components.
//!
//! Neither `authority()` nor `to_string()` hands back a slice of the original
//! input — both are rebuilt from the parsed fields, which is why they can
//! differ from what was passed in. `"http://example.com:abc"` re-serialises as
//! `"http://example.com"` because the unusable port is simply gone, and
//! `"http://h/?"` loses its empty query.

use super::port::NO_PORT;
use super::Parts;

/// Rebuilds the authority as `[userinfo "@"] host [":" port]`.
///
/// The `@` appears whenever the userinfo is non-empty and the `:port` whenever
/// a port was accepted, independently of whether the host is empty — so an
/// empty host with a port renders as `":8080"`.
pub fn authority(parts: &Parts) -> Vec<u8> {
    let mut out = Vec::new();
    if !parts.userinfo.is_empty() {
        out.extend_from_slice(&parts.userinfo);
        out.push(b'@');
    }
    out.extend_from_slice(&parts.host);
    if parts.port != NO_PORT {
        out.push(b':');
        out.extend_from_slice(parts.port.to_string().as_bytes());
    }
    out
}

/// Rebuilds the whole URL.
///
/// The scheme guards the authority: with an empty scheme neither `://` nor the
/// authority is emitted, so `"://h/p"` serialises as just `"/p"`. The `?` and
/// `#` markers are emitted only for non-empty components.
pub fn to_string(parts: &Parts) -> Vec<u8> {
    let mut out = Vec::new();
    if !parts.scheme.is_empty() {
        out.extend_from_slice(&parts.scheme);
        out.extend_from_slice(b"://");
        out.extend_from_slice(&authority(parts));
    }
    out.extend_from_slice(&parts.path);
    if !parts.query.is_empty() {
        out.push(b'?');
        out.extend_from_slice(&parts.query);
    }
    if !parts.fragment.is_empty() {
        out.push(b'#');
        out.extend_from_slice(&parts.fragment);
    }
    out
}

